using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.NativeContinuation.Acquisition;

internal sealed class NativeBinaryWordDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Binary output of the original successful word and complete suffix table.",
        H("Original native binary word acquisition"),
        Blocks(
            Paragraph(Text("The original guard forbids a true seam followed by a window with a true last bit. The successor is the window first bit. Distinct modes retain separate permission bits even when they share a successor.")),
            Paragraph(Text("The acquired table is retained unchanged while a physical scan accumulates the positivity of each of its two binary counts. The first allowed mode with positive child count supplies the next original window. The existing natural reconstruction theorem connects those choices to the original histories and integer reader.")),
            Paragraph(Text("The complete execution includes the seam read, input copy, backward table, actual zero test, permission reads, window writes and final table and word output. The counted stack execution is bounded by 4096 times (L+1) squared. The existing binary simulation turns this into a single quartic bound for the same complete program.")),
            Describe.Lean(DescribeId.Create("native-word-control"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.Control"), H("Control"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The finite labels retain a seam, two positivity flags, a five-mode permission mask and a bounded position inside a mask or a printed window. No label stores a horizon or an unbounded word."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-walk"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.walk"), H("walk"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The controller pops the actual seam, scans the marked binary counts, rejects a zero initial count, and otherwise selects the first allowed mode whose child count is positive. It pushes the original low, middle, high bits of each selected window."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-walkencoding"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.walkEncoding"), H("walkEncoding"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A finite product encoding directly reuses the existing row controller for finite masks and small positions. The inverse law holds on every reconstruction label."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-printed"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.printed"), H("printed"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Each original window contributes its three low-to-high printed bits. The window order is the original high-to-low sequence, and all zero windows remain present."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-input"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.input"), H("input"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The initial seam bit precedes the two terminal membership bits and all five-bit restriction masks. The total input length is three plus five times the horizon."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-readseam"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.readSeam"), H("readSeam"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Three primitive instructions read the seam and preserve it in an extra frame register while the backward table is acquired."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-prepare"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.prepare"), H("prepare"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Physical clears, a preserving table copy and a saved-input reversal install the forward restriction stream and the table scan. All cleared storage and all transfers are counted."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-finish"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.finish"), H("finish"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Physical transfers preserve the complete table as an output prefix and append the decision bit and the reconstructed word. Failure has a false status and no word bits; the successful empty word has a true status."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-program"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.program"), H("program"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("One fixed finite program reads the seam, preserves the explicit input, acquires the full table using the existing table program, reconstructs or reports failure, and writes the combined output."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-encoding"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.encoding"), H("encoding"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Finite sums and products combine the seam reader, preserving copy, table program, preparation, reconstruction and output continuations."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-stackmachine"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.stackMachine"), H("stackMachine"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The existing finite-instruction compiler produces the counted nine-register Boolean-stack machine."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-binarymachine"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.binaryMachine"), H("binaryMachine"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The existing single-tape binary compiler supplies the actual machine, including input initialization, storage, access, control and physical output."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-output"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.output"), H("output"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("All original suffix rows form the output prefix. The following status bit and low-to-high window codes encode the original deterministic reconstruction result."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-decodeword"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.decodeWord"), H("decodeWord"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Groups of three printed bits decode to the five original windows; other bit triples and incomplete triples are rejected."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-decodeanswer"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.decodeAnswer"), H("decodeAnswer"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The status bit distinguishes failure from a successful word of length zero. Successful payloads decode using the original three-bit window codes."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-word-native-binary-word"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryWord.native_binary_word"), H("native_binary_word"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every finite horizon L, explicit family A of original allowed-window sets, terminal set B and initial seam s, the same fixed binary program reads exactly 3+5L bits. It outputs every original successful-suffix count for both seams, each bounded by five to the remaining horizon, then reports failure exactly when the initial count is zero. A positive count yields an actual allowed length-L word ending in B, with the original NativeHistory and rawMachine 0 execution. The physically printed table prefix and word payload decode exactly. One universal bound of 1073741824 times (L+1) to the fourth power covers the complete binary execution, including initialization, all integer work, table and word storage, access, control and output. The theorem includes the empty horizon, both seams, empty or full terminal sets, empty restrictions and zero rows. It makes no random sampling assertion."))), DescribeRole.Theorem)),
        [DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryTable"))]));
}
